2042	+func (s *WorkspaceService) ListWorkspaces(ctx context.Context) ([]domain.WorkspaceSummary, error) {
2043	+	rows, err := s.db.ListWorkspaces(ctx)
2044	+	if err != nil {
2045	+		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
2046	+	}
2047	+
2048	+	// Batch-load latest sync run per workspace to avoid N+1 queries.
2049	+	allRuns, _ := s.db.ListLatestSyncRunsPerWorkspace(ctx)
2050	+	runMap := make(map[string]database.WorkspaceSyncRun, len(allRuns))
2051	+	for _, run := range allRuns {
2052	+		runMap[database.UUIDString(run.WorkspaceID)] = run
2053	+	}
