2055	+	out := make([]domain.WorkspaceSummary, 0, len(rows))
2056	+	for _, r := range rows {
2057	+		wsID := database.UUIDString(r.ID)
2058	+		srcRun, ok := runMap[wsID]
2059	+		var ss domain.SourceState
2060	+		if ok {
